    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "We used the PICO (Population, Intervention, Comparison, Outcome) search format: Among adults with cardiac arrest in any setting (OHCA or IHCA) who qualify for ECPR by inclusion and exclusion parameters outlined (P), does receiving ECPR, including ECMO or cardiopulmonary bypass, during cardiac arrest (I), compared to manual CPR and/or mechanical CPR (C) without any mechanical circulatory support, change meaningful outcomes (favourable neurological status or survival at study end) (O). Contemporary studies from January 2000 to June 2021 were included. Only English language studies were included. Randomised trials, non-randomised controlled trials, and observational studies (cohort studies and casecontrol studies) were included. The population included adults (age above 12) with IHCA or OHCA of any origin. Animal studies, ecological studies, case reports, reviews, abstracts, editorials, comments, and letters to the editor were excluded. Studies with ≤ 5 patients receiving ECPR or studies that did not report the inclusion or exclusion criteria regarding the eligibility of ECPR or the timing of ECPR (i.e. during or after cardiac arrest) were excluded.",
      "reason": "The text explicitly specifies PICO components, eligible study designs, settings (OHCA/IHCA), and follow-outcome definitions (survival at study end)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Contemporary studies from January 2000 to June 2021 were included. Only English language studies were included.",
      "reason": "The text specifies the dissemination year range and language restriction."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The text does not distinguish between exclusion due to outcomes not being measured versus outcomes not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Results are reported separately for pre-defined subgroups based on type of study (retrospective or prospective), and the location of cardiac arrest (IHCA vs OHCA).",
      "reason": "The text specifies the groups used for synthesis (study type, location) and links them to the analysis."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The text lists eligibility restrictions (e.g., English only, ≤5 patients) but does not provide explicit rationales for these notable restrictions."
    }
  ],
  "confidence": 95
}

